export interface OpenDocument {
  path: string;
  name: string;
  uri: string;
  content: string;
  dirty: boolean;
  /** 是否位于 game/scene 目录下 (启用 LSP 语言能力) */
  isScene: boolean;
}

export interface LspDiagnostic {
  range: {
    start: { line: number; character: number };
    end: { line: number; character: number };
  };
  severity: number;
  message: string;
  /** 诊断错误码 (如 WG001), 服务端以字符串或数字发送 */
  code?: number | string;
  source?: string;
}

export type LspStatus = 'disconnected' | 'connecting' | 'ready' | 'error';

export type SettingsCategory = 'editor' | 'engine' | 'template' | 'about';

/** 一次"跳到某处"的请求 (诊断列表点击行发起)。 */
export interface RevealRequest {
  path: string;
  line: number;
  column: number;
  /**
   * 该处诊断的结束位置 (1 起算)。有值时编辑器**选中整段**而不只是放一个光标 —— 用户点一条诊断
   * 就是想看"被标出来的是哪几个字"; 没有对应诊断时留空, 编辑器退回"只放光标"。
   */
  endLine?: number;
  endColumn?: number;
  token: number;
}

/** 一次"重跑这一行"的请求 (实时预览指示器点击发起)。 */
export interface PreviewReplayRequest {
  token: number;
  line: number;
}

/** 光标位置, 带上所属文档路径。 */
export interface CursorPosition {
  path: string;
  line: number;
  column: number;
}

interface AppStateShape {
  settings: Settings;
  theme: Exclude<ThemePreference, 'system'>;

  projectPath: string | null;
  projectName: string | null;
  /** 项目绑定 (key: 规范化项目路径 -> 引擎/模板 id) */
  projectBindings: Record<string, ProjectBinding>;

  // -------- 选项卡 (单一有序序列) --------
  /**
   * 编辑器内的全部选项卡, 混合场景/文件、文本预处理、差异比较与配音工作台。
   * 顺序即显示顺序, 可任意拖拽重排。
   */
  tabs: WorkbenchTabItem[];
  /** 当前活动选项卡 id; `null` 表示没有打开任何选项卡 */
  activeTabId: string | null;
  /** 最近使用过的 tab 历史，用于 ctrl+tab / 前后切换 */
  tabHistory: string[];
  /** 已打开文档 (仅场景/文件选项卡有对应文档) */
  documents: OpenDocument[];
  /** 文本预处理选项卡的编辑器统计 (供状态栏显示)。 */
  novelStats: { chars: number; lines: number } | null;

  /** git 仓库状态 (null 表示尚未加载)。 */
  gitStatus: GitStatus | null;

  lspStatus: LspStatus;
  lspError: string | null;
  /** 语言服务"忙"时的说明 */
  lspActivity: string | null;

  diagnostics: Record<string, LspDiagnostic[]>;
  /** 诊断列表 (弹窗或底部托盘) 是否打开。 */
  diagnosticsOpen: boolean;
  /** 一次"跳到某条诊断"的请求 (诊断列表点击行发起)。 */
  revealRequest: RevealRequest | null;

  previewServerUrl: string | null;
  previewSiteId: string | null;
  previewReady: boolean;
  /** 实时预览的行号指示器状态 (行号旁那个图标)。 */
  livePreviewMarker: LivePreviewMarker | null;
  /** 一次"重跑这一行"的请求 (由指示器点击发起)。 */
  previewReplay: PreviewReplayRequest | null;

  /** 当前光标位置 (状态栏显示 / 配音卡定位用)。 */
  cursor: CursorPosition | null;
  /** 每个文档各自的光标位置, 切走再切回来时恢复。 */
  cursors: Record<string, { line: number; column: number }>;

  // -------- 配音工作流 --------
  /** GSOV 服务状态 */
  voiceStatus: GsvStatus;
  /** GSOV 状态详情 (错误信息等) */
  voiceStatusDetail: string | null;
  /** GSOV 进程日志 */
  voiceLogs: string[];
  /** 角色列表 */
  voiceCharacters: Character[];
  /** 场景配音编辑器状态 (key 为场景路径) */
  sceneVoiceEditors: Map<string, SceneVoiceState>;
  /** 配音缓存条目 */
  voiceCache: CacheEntry[];
  /** 场景级角色覆盖: 场景路径 -> (说话者 -> 角色 id) */
  voiceAssignments: Record<string, Record<string, string>>;
  /** 递增令牌: 队列状态变化时触发订阅者重渲染 */
  voiceTick: number;
  /** 待处理 + 运行中的配音任务数 (供工作台选项卡显示角标) */
  voiceQueuePending: number;
  /** 处于配音编辑模式的场景路径 (仅在配音工作台打开时有意义) */
  voiceModePaths: string[];
  /** 最近一次处于选中态的场景卡 id。 */
  currentSceneTabId: string | null;

  settingsOpen: boolean;
  unsavedDialog: boolean;
  /** 通用确认框是否打开 */
  confirmDialog: boolean;
  /** 打开设置时定位到的分类 */
  settingsCategory: SettingsCategory;
  /** 预览刷新令牌 (自增触发 iframe 整体重挂) */
  previewReloadToken: number;
}

