export const actions = {
  setTheme(theme: Exclude<ThemePreference, 'system'>): void {
    appStore.theme = theme;
    changed();
  },

  updateSettings(patch: Partial<Settings>): void {
    const next = { ...appStore.settings, ...patch };
    saveSettings(next);
    const wasAutoSync = appStore.settings.autoSyncPreview;
    appStore.settings = next;
    // 关掉「预览」开关就是关掉整套实时预览: 指示器一并撤下, 不留残影
    if (wasAutoSync && !next.autoSyncPreview) appStore.livePreviewMarker = null;
    changed();
  },

  /** 设置当前项目; `name` 为 config.txt 里的游戏名 (缺省时用目录名) */
  setProject(path: string | null, name?: string | null): void {
    if (path) {
      const fallback =
        path
          .replace(/[\\/]+$/, '')
          .split(/[\\/]/)
          .pop() ?? path;
      appStore.projectPath = path;
      appStore.projectName = name?.trim() || fallback;
      changed();
      return;
    }
    appStore.projectPath = null;
    appStore.projectName = null;
    appStore.tabs = [];
    appStore.activeTabId = null;
    appStore.tabHistory = [];
    appStore.documents = [];
    appStore.novelStats = null;
    appStore.gitStatus = null;
    appStore.diagnostics = {};
    // 诊断列表显示的是"当前项目的问题", 项目都关了就没有可看的东西
    appStore.diagnosticsOpen = false;
    appStore.revealRequest = null;
    appStore.previewSiteId = null;
    appStore.previewReady = false;
    appStore.livePreviewMarker = null;
    appStore.previewReplay = null;
    appStore.voiceModePaths = [];
    appStore.currentSceneTabId = null;
    changed();
  },

  /** 设置项目绑定 (模板) 并持久化 */
  setProjectBinding(projectPath: string, binding: ProjectBinding): void {
    const projectBindings = persistBindingsAndReturn(appStore.projectBindings, projectPath, binding);
    appStore.projectBindings = projectBindings;
    changed();
  },

  // -------- 选项卡 --------

  /** 打开 (或聚焦) 一个场景/文件选项卡 */
  openSceneTab(path: string, name: string): void {
    const existing = appStore.tabs.find((tab) => tab.kind === 'scene' && tab.path === path);
    actions.openTab(existing ?? makeSceneTab(path, name));
  },

  /** 打开 (或聚焦) 一个任意选项卡 */
  openTab(tab: WorkbenchTabItem): void {
    const { tabs, activeId } = insertTab(appStore.tabs, tab, appStore.activeTabId);
    // 注意: 打开场景卡**不会**自动进入配音编辑模式。进入与否完全由用户点麦克风决定,
    // 否则"切到的每个场景都变成配音卡"。
    const tabHistory = rememberTabActivation(appStore.tabHistory, activeId);
    appStore.tabs = tabs;
    appStore.activeTabId = activeId;
    appStore.tabHistory = tabHistory;
    if (tab.kind === 'scene') appStore.currentSceneTabId = tab.id;
    changed();
  },

  /** 关闭选项卡 (会按需由调用方先处理未保存确认) */
  closeTab(id: string): void {
    const closed = appStore.tabs.find((tab) => tab.id === id);
    const { tabs, activeId } = closeTabInOrder(appStore.tabs, id, appStore.activeTabId, appStore.tabHistory);
    const nextHistory = appStore.tabHistory.filter((tabId) => tabId !== id && tabs.some((tab) => tab.id === tabId));
    appStore.tabs = tabs;
    appStore.activeTabId = activeId;
    appStore.tabHistory = activeId ? rememberTabActivation(nextHistory, activeId) : nextHistory;
    /*
     * 关掉场景卡**不清理**它的诊断: 诊断按项目整体推送 (没有问题的场景也推空数组), 这份表一直
     * 是"整个项目的现状", 与文件此刻是否开着无关 —— 清掉会让项目诊断列表随开关标签页时有时无。
     */
    const closingWorkbench = closed?.kind === 'voice-workbench';
    // 关闭场景卡时顺带清掉它的配音编辑模式, 避免残留到下次打开
    if (closed?.kind === 'scene') {
      appStore.voiceModePaths = appStore.voiceModePaths.filter((path) => path !== closed.path);
    }
    // 关掉的若是当前场景卡, 退回到仍然存在的场景卡 (优先新选中的那张); 关掉工作台时活动项
    // 会落到邻居上, 这条同时覆盖那种情况。
    const nextTab = tabs.find((tab) => tab.id === activeId);
    if (appStore.currentSceneTabId === null || appStore.currentSceneTabId === id) {
      appStore.currentSceneTabId =
        nextTab?.kind === 'scene' ? nextTab.id : (tabs.find((tab) => tab.kind === 'scene')?.id ?? null);
    }
    // 关闭工作台即退出配音功能
    if (closingWorkbench) appStore.voiceModePaths = [];
    changed();
  },

  /*
   * 切换选项卡**不改变**任何场景的配音编辑模式: 进入与退出只有当前场景卡上的麦克风一个入口,
   * 自动规则会把麦克风开关覆盖掉 (点了没反应)。
   *
   * 顺带清空光标: 它是**全局**状态, 切卡时上一条记录的行号会被新文档继承, 于是配音卡一挂载
   * 就拿着"上一张卡的光标行"去选中对话 —— 选错行, 甚至因为该行不是对话而清空整张卡。
   */
  activateTab(id: string): void {
    const tab = appStore.tabs.find((item) => item.id === id);
    // 只记住"最近选中的场景卡": 切到工作台/说明页时它保持不变。
    const nextSceneTabId = tab?.kind === 'scene' ? tab.id : appStore.currentSceneTabId;
    if (appStore.activeTabId === id && appStore.currentSceneTabId === nextSceneTabId) return;
    appStore.activeTabId = id;
    appStore.tabHistory = rememberTabActivation(appStore.tabHistory, id);
    appStore.currentSceneTabId = nextSceneTabId;
    appStore.cursor = null;
    changed();
  },

  /** 选项卡拖拽排序 */
  moveTab(id: string, toIndex: number): void {
    appStore.tabs = moveTab(appStore.tabs, id, toIndex);
    changed();
  },

  /** 按给定顺序整体重排选项卡 (右键菜单「整理标签页」)。 */
  sortTabs(tabs: WorkbenchTabItem[]): void {
    appStore.tabs = tabs;
    changed();
  },

  /** 文档被重命名/移动后, 把对应场景选项卡迁移到新路径 (保持原位置) */
  retargetSceneTabs(oldPath: string, newPath: string): void {
    const oldLower = oldPath.replace(/\\/g, '/').toLowerCase();
    const tabs = appStore.tabs.map((tab) => {
      if (tab.kind !== 'scene') return tab;
      const current = tab.path.replace(/\\/g, '/').toLowerCase();
      if (current !== oldLower && !current.startsWith(`${oldLower}/`)) return tab;
      // 目录重命名时保留原相对部分
      const suffix = tab.path.replace(/\\/g, '/').slice(oldPath.replace(/\\/g, '/').length);
      const nextPath = `${newPath.replace(/\\/g, '/')}${suffix}`.replace(/\//g, '\\');
      return makeSceneTab(nextPath, nextPath.split(/[\\/]/).pop() ?? nextPath);
    });
    appStore.tabs = tabs;
    appStore.activeTabId =
      tabs.find((tab) => tab.id === appStore.activeTabId)?.id ??
      tabs.find((tab) => tab.kind === 'scene')?.id ??
      appStore.activeTabId;
    changed();
  },

  // 打开配音工作台**不改变**场景的配音编辑模式: 是否进入只由当前场景卡上的麦克风决定,
  // 自动开启会让人以为"打开工作台 = 所有场景都变成配音卡"。
  openVoiceWorkbench(): void {
    const { tabs, activeId } = insertTab(appStore.tabs, makeWorkbenchTab(), appStore.activeTabId);
    appStore.tabs = tabs;
    appStore.activeTabId = activeId;
    appStore.tabHistory = rememberTabActivation(appStore.tabHistory, activeId);
    changed();
  },

  closeVoiceWorkbench(): void {
    const { tabs, activeId } = closeTabInOrder(
      appStore.tabs,
      WORKBENCH_TAB_ID,
      appStore.activeTabId,
      appStore.tabHistory
    );
    const nextHistory = appStore.tabHistory.filter(
      (tabId) => tabId !== WORKBENCH_TAB_ID && tabs.some((tab) => tab.id === tabId)
    );
    appStore.tabs = tabs;
    appStore.activeTabId = activeId;
    appStore.tabHistory = activeId ? rememberTabActivation(nextHistory, activeId) : nextHistory;
    appStore.voiceModePaths = [];
    changed();
  },

  openVoiceGuide(): void {
    const { tabs, activeId } = insertTab(appStore.tabs, makeVoiceGuideTab(), appStore.activeTabId);
    appStore.tabs = tabs;
    appStore.activeTabId = activeId;
    appStore.tabHistory = rememberTabActivation(appStore.tabHistory, activeId);
    changed();
  },

  // -------- 文档 --------

  openDocument(doc: OpenDocument): void {
    const index = appStore.documents.findIndex((item) => item.path === doc.path);
    if (index >= 0) {
      appStore.documents[index] = { ...appStore.documents[index], ...doc };
    } else {
      appStore.documents.push(doc);
    }
    changed();
  },

  closeDocument(path: string): void {
    appStore.documents = appStore.documents.filter((doc) => doc.path !== path);
    changed();
  },

  updateDocument(path: string, patch: Partial<OpenDocument>): void {
    const doc = appStore.documents.find((item) => item.path === path);
    if (doc) Object.assign(doc, patch);
    changed();
  },

  setNovelStats(stats: { chars: number; lines: number } | null): void {
    appStore.novelStats = stats;
    changed();
  },

  /** 打开一个文本预处理选项卡 (非单例; id 全局唯一) */
  addNovelTab(tab: WorkbenchTabItem): void {
    const { tabs, activeId } = insertTab(appStore.tabs, tab, appStore.activeTabId);
    appStore.tabs = tabs;
    appStore.activeTabId = activeId;
    appStore.tabHistory = rememberTabActivation(appStore.tabHistory, activeId);
    changed();
  },

  /**
   * 更新 git 状态。**内容没变就不写** (见 `git/compare.ts`): 项目里任何文件变化后 `git/status.ts`
   * 都会重跑 `git status`, 编辑器自己的自动保存也落盘 —— 每打一次字都会被触发一次; 内容一样时
   * 下发新对象只会让编辑器把行号旁的色块、仓库页的列表与状态栏全部重画一遍。
   */
  setGitStatus(status: GitStatus | null): void {
    if (sameGitStatus(appStore.gitStatus, status)) return;
    appStore.gitStatus = status;
    changed();
  },

  setLspStatus(status: LspStatus, error?: string): void {
    appStore.lspStatus = status;
    appStore.lspError = error ?? null;
    changed();
  },

  /**
   * 语言服务当前的"忙"说明 (null = 不忙)。连接还在、状态还是 ready 不代表答得上来: 处理大批
   * 文件变更时它会长时间不给答复, 状态栏必须说出来, 否则用户看到的是"卡死了, 但写着就绪"。
   */
  setLspActivity(activity: string | null): void {
    appStore.lspActivity = activity;
    changed();
  },

  setDiagnostics(path: string, diagnostics: LspDiagnostic[]): void {
    appStore.diagnostics[path] = diagnostics;
    changed();
  },

  /** 清掉某个路径 (若为目录, 含其下所有文件) 的诊断 —— 文件被删除时调用 */
  clearDiagnostics(path: string): void {
    // 目录也走这里: 删掉整个场景文件夹时, 底下的文件都要一起清掉
    const prefix = `${path.replace(/\\/g, '/').replace(/\/+$/, '').toLowerCase()}/`;
    const entries = Object.entries(appStore.diagnostics).filter(([key]) => {
      const normalized = key.replace(/\\/g, '/').toLowerCase();
      return normalized !== prefix.slice(0, -1) && !normalized.startsWith(prefix);
    });
    if (entries.length === Object.keys(appStore.diagnostics).length) return;
    appStore.diagnostics = Object.fromEntries(entries);
    changed();
  },

  /** 文件/目录被重命名后, 把诊断挪到新路径 (键是路径, 不挪就会留下指向旧路径的幽灵条目) */
  retargetDiagnostics(oldPath: string, newPath: string): void {
    const oldNorm = oldPath.replace(/\\/g, '/').replace(/\/+$/, '').toLowerCase();
    const oldPosix = oldPath.replace(/\\/g, '/').replace(/\/+$/, '');
    const newPosix = newPath.replace(/\\/g, '/').replace(/\/+$/, '');
    let changedAny = false;
    const next: Record<string, LspDiagnostic[]> = {};
    for (const [key, value] of Object.entries(appStore.diagnostics)) {
      const posix = key.replace(/\\/g, '/');
      const normalized = posix.toLowerCase();
      if (normalized !== oldNorm && !normalized.startsWith(`${oldNorm}/`)) {
        next[key] = value;
        continue;
      }
      changedAny = true;
      const suffix = posix.slice(oldPosix.length);
      next[`${newPosix}${suffix}`.replace(/\//g, '\\')] = value;
    }
    if (!changedAny) return;
    appStore.diagnostics = next;
    changed();
  },

  setDiagnosticsOpen(open: boolean): void {
    appStore.diagnosticsOpen = open;
    changed();
  },

  /**
   * 请求跳到某条诊断所在的位置 (由编辑器消费); 带上结束位置以便**整段选中**。
   *
   * `end` 由调用方 (诊断列表) 直接给出 —— 列表手上的 `DiagnosticEntry` 本来就有
   * `endLine`/`endColumn`; 省略时回原始诊断表反查兜底, 反查的行列口径一旦对不上就会静默退化
   * 成"只放光标", 也就是用户看到的"点了诊断但没选中"。
   */
  requestReveal(path: string, line: number, column: number, end?: { line: number; column: number }): void {
    const resolved = end ?? diagnosticEndAt(appStore.diagnostics[path], line, column);
    appStore.revealRequest = {
      path,
      line,
      column,
      endLine: resolved?.line,
      endColumn: resolved?.column,
      token: (appStore.revealRequest?.token ?? 0) + 1,
    };
    changed();
  },

  /**
   * 消费掉那次跳转请求。请求是"一次性动作"而不是"当前状态": 不清掉的话, 跳到别处再切回这个
   * 文件时会又跳一次 (那时用户想回到的是自己上次的光标, 不是刚才看的那条诊断)。
   */
  clearReveal(): void {
    appStore.revealRequest = null;
    changed();
  },

  /**
   * 写预览站点 / 会话 / 就绪态。
   *
   * **值没变就不写、不通知** (与 `setGitStatus` 同一惯例): `previewClient.ensureSite()` 命中站点
   * 缓存时会把**同一份**值反复写回 store, 而调用它的正是组件里的 `$effect` —— 无条件写会让
   * "调用方 effect 被自己的写入惊醒"变成回路 (见 `changed()`)。
   *
   * 比较本身也要 `untrack`: 否则读一次这些字段就让调用方 effect 依赖它们, 值真变了又会被自己
   * 的写惊醒。
   */
  setPreview(patch: Partial<Pick<AppStateShape, 'previewServerUrl' | 'previewSiteId' | 'previewReady'>>): void {
    const current = untrack(() => ({
      previewServerUrl: appStore.previewServerUrl,
      previewSiteId: appStore.previewSiteId,
      previewReady: appStore.previewReady,
    }));
    const next = { ...current, ...patch };
    const same =
      Object.is(next.previewServerUrl, current.previewServerUrl) &&
      Object.is(next.previewSiteId, current.previewSiteId) &&
      Object.is(next.previewReady, current.previewReady);
    if (same) return;

    Object.assign(appStore, patch);
    changed();
  },

  /**
   * 预览把光标行同步给引擎时记下这一行 (指示器立即进入"执行中")。
   *
   * `autoSyncPreview` 关闭时无条件清空 —— 「预览」开关就是这个功能的开关, 关掉后编辑器里不该
   * 再留下实时预览的痕迹。**内容没变就不写 store** (见 `sameLivePreviewMarker`): `syncScene` 每次
   * 都新造一个等价对象, 无条件接受会让指示器装饰被反复拆画, 去重放在源头即可。
   */
  beginLivePreview(marker: LivePreviewMarker): void {
    const next = appStore.settings.autoSyncPreview ? marker : null;
    if (sameLivePreviewMarker(appStore.livePreviewMarker, next)) return;
    appStore.livePreviewMarker = next;
    changed();
  },

  /**
   * 按引擎回灌推进指示器 (成功 / 失败 / 与本次无关则原样保留)。折算函数在"没有变化"时返回
   * **原对象**, 因此这里比引用就能跳过无变化的写。
   */
  applyLivePreviewEvent(fold: (marker: LivePreviewMarker) => LivePreviewMarker): void {
    const current = appStore.livePreviewMarker;
    if (!current) return;
    const next = fold(current);
    if (sameLivePreviewMarker(current, next)) return;
    appStore.livePreviewMarker = next;
    changed();
  },

  /** 请求重跑某一行 (指示器点击) */
  requestPreviewReplay(line: number): void {
    appStore.previewReplay = { token: (appStore.previewReplay?.token ?? 0) + 1, line };
    changed();
  },

  /**
   * 消费掉重跑请求 (编辑器发出同步之后调用)。与诊断跳转的 `clearReveal` 同构: 一次性动作不清掉
   * 的话, 之后任何让 effect 重跑的依赖变化都会把**上一次**的重跑再发一遍 —— 用户只是重新连上了
   * 预览, 却看到引擎又跑了一次。
   */
  clearPreviewReplay(): void {
    if (!appStore.previewReplay) return;
    appStore.previewReplay = null;
    changed();
  },

  setCursor(cursor: CursorPosition | null): void {
    appStore.cursor = cursor;
    changed();
  },

  /** 记下某个文档的光标位置 (切走再切回来时恢复) */
  rememberCursor(path: string, cursor: { line: number; column: number }): void {
    const previous = appStore.cursors[path];
    if (previous && previous.line === cursor.line && previous.column === cursor.column) return;
    appStore.cursors[path] = cursor;
    changed();
  },

  // -------- 配音 --------

  /** 设置某个场景的配音编辑模式开关 */
  setVoiceMode(path: string, enabled: boolean): void {
    const has = appStore.voiceModePaths.includes(path);
    if (enabled === has) return;
    appStore.voiceModePaths = enabled
      ? [...appStore.voiceModePaths, path]
      : appStore.voiceModePaths.filter((item) => item !== path);
    changed();
  },

  setVoiceStatus(status: GsvStatus, detail?: string | null): void {
    appStore.voiceStatus = status;
    appStore.voiceStatusDetail = detail ?? null;
    changed();
  },

  setVoiceLogs(logs: string[]): void {
    appStore.voiceLogs = logs;
    changed();
  },

  appendVoiceLog(line: string): void {
    const voiceLogs = [...appStore.voiceLogs, line];
    // 日志缓冲上限, 避免长时间运行后内存膨胀
    if (voiceLogs.length > 500) voiceLogs.splice(0, voiceLogs.length - 500);
    appStore.voiceLogs = voiceLogs;
    changed();
  },

  setVoiceCharacters(characters: Character[]): void {
    appStore.voiceCharacters = characters;
    changed();
  },

  setSceneVoiceEditors(cards: Map<string, SceneVoiceState>): void {
    appStore.sceneVoiceEditors = new Map(cards);
    changed();
  },

  setVoiceCache(cache: CacheEntry[]): void {
    appStore.voiceCache = cache;
    changed();
  },

  upsertVoiceCache(entry: CacheEntry): void {
    const rest = appStore.voiceCache.filter((item) => item.hash !== entry.hash);
    appStore.voiceCache = [entry, ...rest];
    changed();
  },

  setVoiceAssignment(scenePath: string, assignments: Record<string, string>): void {
    appStore.voiceAssignments[scenePath] = assignments;
    changed();
  },

  /**
   * 语音卡计数 +1 (配音控制器用它驱动重算)。
   *
   * `untrack` 的理由与 `changed()` 完全一样: 读+写同一个字段, 会让"在 effect 体内调用本
   * action"的调用方被自己的写入惊醒。
   */
  setVoiceTick(): void {
    untrack(() => {
      appStore.voiceTick += 1;
    });
    changed();
  },

  setVoiceQueuePending(count: number): void {
    appStore.voiceQueuePending = count;
    changed();
  },

  // -------- 对话框与令牌 --------

  setSettingsOpen(open: boolean): void {
    appStore.settingsOpen = open;
    changed();
  },

  setSettingsCategory(category: SettingsCategory): void {
    appStore.settingsCategory = category;
    changed();
  },

  setUnsavedDialog(open: boolean): void {
    appStore.unsavedDialog = open;
    changed();
  },

  setConfirmDialog(open: boolean): void {
    appStore.confirmDialog = open;
    changed();
  },

  /** 刷新预览 iframe 的令牌 (读取方 `PreviewPanel` 靠它重挂; `untrack` 的理由同 `setVoiceTick`)。 */
  requestPreviewReload(): void {
    untrack(() => {
      appStore.previewReloadToken += 1;
    });
    changed();
  },
};

/**
 * 绑定表写入并返回新表。
 *
 * 单独抽出来是因为 `lib/bindings.ts` 的 `withBinding` 只做合并, 持久化在 `persistBindings`;
 * store 这里两者都要。
 */
function persistBindingsAndReturn(
  bindings: Record<string, ProjectBinding>,
  projectPath: string,
  binding: ProjectBinding
): Record<string, ProjectBinding> {
  const next = withBinding(bindings, projectPath, binding);
  persistBindings(next);
  return next;
}

export { VOICE_GUIDE_TAB_ID, WORKBENCH_TAB_ID, makeSceneTab, makeWorkbenchTab, makeVoiceGuideTab };
export type { WorkbenchTabItem };

// 选择器是纯函数, 定义在 `selectors.ts` (便于 node 环境单测)。这里再导出一次, 让「状态与
// 读状态」只有一个入口, 调用方不需要记住两个路径。
export {
  activeConfigDocumentOf,
  activeConfigTabOf,
  activeResourceDocumentOf,
  activeResourceTabOf,
  activeSceneDocumentOf,
  activeSceneTabOf,
  activeTabOf,
  hasTabs,
  isVoiceWorkbenchActive,
  isVoiceWorkbenchOpen,
  shouldShowVoiceToggle,
} from './selectors';

/**
 * 全局单例状态的组装: 先造普通对象 → 把 `actions` 挂成它的属性 → 整体交给 `$state`。
 *
 * 顺序不能换: `$state` 只在对象初始化时建立代理的完整性, 之后再挂新属性不会被可靠地纳入响应式
 * 追踪, 而全仓依赖 `getState().someAction(...)` 这种形状 (action 必须能从状态上取到)。class 也
 * 不行 —— 实例方法不是自有属性, `$state` 不会把它们暴露给调用方。
 */
function createInitialState(): AppStateShape {
  return {
    settings: loadSettings(),
    theme: 'light',

    projectPath: null,
    projectName: null,
    projectBindings: loadBindings(),

    tabs: [],
    activeTabId: null,
    tabHistory: [],
    documents: [],
    novelStats: null,

    gitStatus: null,

    lspStatus: 'disconnected',
    lspError: null,
    lspActivity: null,

    diagnostics: {},
    diagnosticsOpen: false,
    revealRequest: null,

    previewServerUrl: null,
    previewSiteId: null,
    previewReady: false,
    livePreviewMarker: null,
    previewReplay: null,

    cursor: null,
    cursors: {},

    voiceStatus: 'stopped',
    voiceStatusDetail: null,
    voiceLogs: [],
    voiceCharacters: [],
    sceneVoiceEditors: new Map(),
    voiceCache: [],
    voiceAssignments: {},
    voiceTick: 0,
    voiceQueuePending: 0,
    voiceModePaths: [],
    currentSceneTabId: null,

    settingsOpen: false,
    unsavedDialog: false,
    confirmDialog: false,
    settingsCategory: 'editor',
    previewReloadToken: 0,
  };
}

/** 状态 + 全部 action 的完整形状。 */
export type AppStore = AppStateShape & typeof actions;

const storeObject: AppStore = Object.assign(createInitialState(), actions) as AppStore;

/** 全局单例。组件直接读它的字段; 非组件代码走下面的 `useAppStore` 门面。 */
export const appStore = $state<AppStore>(storeObject);

// ---------------------------------------------------------------------------
// 订阅通道 (兼容 subscribe(state, previous))
// ---------------------------------------------------------------------------

type StateListener = (state: AppStateShape, previous: AppStateShape) => void;

const stateListeners = new Set<StateListener>();
let restoreStateChannels: (() => void) | null = null;

/**
 * 状态变更计数器 —— 订阅通道的驱动源。
 *
 * 刻意**不放进 `appStore`**: 它是内部记账, 不属于 UI 状态, 混进去会污染 `getState()` 的形状。
 * 用 `$state` 而非普通变量, 是因为订阅通道要能在 `$effect` 里追踪到它。
 */
let stateVersion = $state(0);

/**
 * 标记状态已变化 —— 订阅通道的驱动源。
 *
 * ⚠️ **`stateVersion += 1` 必须包在 `untrack` 里, 这是硬约束。** 它是"先读后写": 读会把当时
 * 正在运行的 effect 登记成 `stateVersion` 的依赖, 紧接着的写又把它标脏 —— 同一个批次里它被
 * 无限重新排程, 直到 Svelte 抛 `effect_update_depth_exceeded` 并占满主线程; 而"在 effect 体内
 * 写一次 store"在本应用里到处都是 (如资源浏览的 `ensureSite` 命中缓存时写回站点信息)。
 *
 * 包上 `untrack` 之后: **读不算依赖, 写照常通知订阅者**。
 */
function changed(): void {
  untrack(() => {
    stateVersion += 1;
  });
}

/**
 * 建立响应式 -> 订阅者的通道。
 *
 * 由"状态已变化"的计数器驱动通知 —— `$effect` 本身只在组件/根作用域里可用, 因此这里用
 * `$effect.root` 开一个游离的根作用域。惰性建立: 没有任何订阅者时不留后置的 effect。
 */
function ensureStateChannel(): void {
  if (restoreStateChannels || stateListeners.size === 0) return;
  let previousVersion = stateVersion;
  let previousSnapshot = snapshotOf();
  restoreStateChannels = $effect.root(() => {
    $effect(() => {
      const version = stateVersion;
      if (version === previousVersion) return;
      previousVersion = version;
      const next = snapshotOf();
      const previous = previousSnapshot;
      previousSnapshot = next;
      for (const listener of [...stateListeners]) listener(next, previous);
    });
  });
}

/** 取一份浅拷贝快照, 用于把 `previous` 交给订阅者。 */
function snapshotOf(): AppStateShape {
  return { ...appStore };
}

/**
 * 兼容层: 让非组件代码 (LSP / 预览 / 配音控制器 / project / fileops / tabs) 与既有测试原样
 * 可用。组件直接读 `appStore` 字段, 需要计算就 `$derived`。
 */
export const useAppStore = {
  /**
   * 读当前状态快照。
   *
   * 返回 `AppStore` (**含全部 action**) 而不是 `AppStateShape` —— 大量调用点形如
   * `getState().someAction(...)`, 类型上必须能取到 action; 运行期它就是 `appStore` 本身。
   */
  getState(): AppStore {
    return appStore;
  },

  /**
   * 按字段合并 (也接受 `(state) => patch` 形式)。
   *
   * 注意它**不做**深度合并。
   */
  setState(patch: Partial<AppStateShape> | ((state: AppStateShape) => Partial<AppStateShape>)): void {
    const resolved = typeof patch === 'function' ? patch(appStore) : patch;
    Object.assign(appStore, resolved);
    changed();
  },

  /** 订阅状态变化; 首次会立即以当前状态调用一次。 */
  subscribe(listener: StateListener): () => void {
    stateListeners.add(listener);
    ensureStateChannel();
    listener(appStore, appStore);
    return () => {
      stateListeners.delete(listener);
    };
  },
};
